public class ReverserCheckerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object verdict(Reverser impl) {
        try {
            return ReverserChecker.isCorrect(impl);
        } catch (Throwable crash) {
            return "isCorrect threw " + crash.getClass().getSimpleName();
        }
    }

    public static void main(String[] args) {
        check("accepts the correct implementation", true, verdict(new CorrectReverser()));
        check("accepts an equally correct implementation", true, verdict(new AlsoCorrectReverser()));
        check("rejects the crash-on-empty-string bug", false, verdict(new CrashOnEmptyReverser()));
        check("rejects the drops-the-last-character bug", false, verdict(new DropsLastCharacterReverser()));
        check("rejects the mangles-repeated-characters bug", false, verdict(new RepeatedCharacterReverser()));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

class CorrectReverser implements Reverser {
    public String reverse(String s) {
        return new StringBuilder(s).reverse().toString();
    }
}

class AlsoCorrectReverser implements Reverser {
    public String reverse(String s) {
        StringBuilder out = new StringBuilder();
        for (int i = s.length() - 1; i >= 0; i--) out.append(s.charAt(i));
        return out.toString();
    }
}

class CrashOnEmptyReverser implements Reverser {
    public String reverse(String s) {
        StringBuilder out = new StringBuilder();
        out.append(s.charAt(s.length() - 1));
        for (int i = s.length() - 2; i >= 0; i--) out.append(s.charAt(i));
        return out.toString();
    }
}

class DropsLastCharacterReverser implements Reverser {
    public String reverse(String s) {
        StringBuilder out = new StringBuilder();
        for (int i = s.length() - 1; i > 0; i--) out.append(s.charAt(i));
        return out.toString();
    }
}

class RepeatedCharacterReverser implements Reverser {
    public String reverse(String s) {
        String rest = s;
        StringBuilder out = new StringBuilder();
        while (!rest.isEmpty()) {
            char last = rest.charAt(rest.length() - 1);
            out.append(last);
            rest = rest.replace(String.valueOf(last), "");
        }
        return out.toString();
    }
}

