/**
 * TASK: Write the checks that decide whether a Reverser is correct.
 *
 * The Reverser contract:
 *   reverse(s) returns the characters of s in the opposite order.
 *   reverse("") returns "" and reverse("a") returns "a".
 *   Examples: reverse("abc") -> "cba", reverse("noon") -> "noon"
 *
 * isCorrect(impl) must return true for an implementation that honours the
 * contract and false for one that does not. One of the broken implementations
 * THROWS instead of returning a value, so a crash counts as a failure: wrap
 * your calls in try/catch and return false if anything is thrown.
 *
 * Think about which inputs actually distinguish implementations: the empty
 * string, a single character, a string whose reverse differs from itself, and
 * a string that REPEATS a character.
 */
interface Reverser {
    /* Provided -- do not edit. */
    String reverse(String s);
}

public class ReverserChecker {

    public static boolean isCorrect(Reverser impl) {
        try {
            if (!"cba".equals(impl.reverse("abc"))) return false;
            if (!"".equals(impl.reverse(""))) return false;
            if (!"a".equals(impl.reverse("a"))) return false;
            if (!"aba".equals(impl.reverse("aba"))) return false;
            if (!"noon".equals(impl.reverse("noon"))) return false;
            if (!"olleh".equals(impl.reverse("hello"))) return false;
        } catch (Throwable crash) {
            return false;
        }
        return true;
    }
}
